{const product=new URLSearchParams(location.search).get('product');const form=document.querySelector('#quote form')||document.querySelector('form');if(form){if(product){const input=document.createElement('input');input.type='hidden';input.name='selected_product';input.value=product;form.append(input);const message=form.querySelector('textarea');if(message&&!message.value)message.value='I am interested in '+product+'.\n';}try{const selected=JSON.parse(localStorage.getItem('elvaro-project')||'[]');if(Array.isArray(selected)&&selected.length){const input=document.createElement('input');input.type='hidden';input.name='selected_products';input.value=JSON.stringify(selected);form.append(input);}}catch{}}}